#include "stdafx.h"#include "HcdElementBase.h"struct SDENC_P{#include "PrivateVars/DENC.h"};class KDENC : public KHcdElementBase  , protected SDENC_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _DENC("DENC", KDENC::Create);IHcdElement *KDENC::Create(){  return new KDENC;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KDENC, 34 )void KDENC::InitParm(){#include "PrivateVars/DENC.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KDENC::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KDENC::StepCalc( SStepCalcParams &params ){  tBool *pIn = &IN1;  tDigital32 count = 0;  tDigital32 code = 0;  tDigital32 mask = 1;  for( int i=0; i<16; ++i, mask = mask << 1 )  {    if( !pIn[i] )      continue;    ++count;    code |= mask;  }  ICNT = count;  DENC = code;}